import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Password Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/02-password-recovery.md","filePath":"02-consumer/02-password-recovery.md"}`),a={name:`02-consumer/02-password-recovery.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="password-recovery" tabindex="-1">Password Recovery <a class="header-anchor" href="#password-recovery" aria-label="Permalink to “Password Recovery”">​</a></h1><p>Password recovery methods:</p><ul><li>Standard recovery via email</li><li>Recovery using Tinker</li><li>Recovery through a database management tool such as phpMyAdmin</li></ul><h2 id="_1-recovery-using-the-forgot-password-form" tabindex="-1">1. Recovery Using the &quot;Forgot Password&quot; Form <a class="header-anchor" href="#_1-recovery-using-the-forgot-password-form" aria-label="Permalink to “1. Recovery Using the &quot;Forgot Password&quot; Form”">​</a></h2><p>The user clicks the &quot;Forgot Password?&quot; link on the login page, enters their account email address, and receives a password reset link via email. By opening the link, they can set a new password.</p><p>This method works provided that the project&#39;s email delivery settings have been configured correctly beforehand. If the password reset email does not arrive, check the email configuration and Laravel logs.</p><h2 id="_2-recovery-using-tinker" tabindex="-1">2. Recovery Using Tinker <a class="header-anchor" href="#_2-recovery-using-tinker" aria-label="Permalink to “2. Recovery Using Tinker”">​</a></h2><p>This method is intended for an administrator or developer who has access to the project&#39;s execution environment. Run the following command in the project terminal:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php artisan tinker</span></span></code></pre></div><p>Then, find the user by email and save the new password:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$user = App\\Models\\User::where(&#39;email&#39;, &#39;user@example.com&#39;)-&gt;firstOrFail();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$user-&gt;password = Illuminate\\Support\\Facades\\Hash::make(&#39;New-Strong-Password&#39;);</span></span>
<span class="line"><span>$user-&gt;save();</span></span></code></pre></div><p>Replace the email address with that of the intended user and the password with a secure value. Do not store the plaintext password in the project code or logs.</p><h2 id="_3-changing-the-password-through-phpmyadmin-or-a-database-management-tool" tabindex="-1">3. Changing the Password Through phpMyAdmin or a Database Management Tool <a class="header-anchor" href="#_3-changing-the-password-through-phpmyadmin-or-a-database-management-tool" aria-label="Permalink to “3. Changing the Password Through phpMyAdmin or a Database Management Tool”">​</a></h2><p>This method is useful when an administrator has access to the database but cannot use Tinker. Do not write a plaintext password directly to the <code>password</code> column; its value must be hashed.</p><p>If PHP CLI is available on the server, you can generate the hash without using Tinker:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php -r &quot;echo password_hash(&#39;New-Strong-Password&#39;, PASSWORD_BCRYPT), PHP_EOL;&quot;</span></span></code></pre></div><p>Copy the output value into the <code>password</code> column for the same user. The following SQL example assumes that the table is named <code>users</code> and the user&#39;s ID is <code>123</code>:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UPDATE users</span></span>
<span class="line"><span>SET password = &#39;PASTE_HASH_HERE&#39;</span></span>
<span class="line"><span>WHERE id = 123;</span></span></code></pre></div><p>In phpMyAdmin, you can also perform this operation by editing the user&#39;s row: enter the generated hash in the <code>password</code> column and save the changes. The table or column name may differ in your project.</p><h3 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h3><ul><li>Email-based recovery is the standard method for users to recover their own passwords.</li><li>Only authorized administrators or support personnel should use Tinker or database management tools.</li><li>Do not send the hash to the user; provide only the new or temporary password through a secure channel.</li><li>After logging in with a temporary password, ask the user to change it.</li></ul><p>Debugging Note: If the user cannot log in after the database has been updated, make sure the hash was stored in the correct column for the correct account and that the project&#39;s hashing method is compatible with bcrypt.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};